/**
 * GATE A11-D — THE ANIMATION DATA IS CONTRACT (SESSION23 A11.3).
 *
 * `OG_ANIMS` is generated by `scripts/anim/transcribeAnims.ts` from the
 * payload's own DefineBinaryData — never hand-keyed (kickoff D4). This file is
 * the trust: the skipIf suite re-parses the SOURCE with its own independent
 * grammar and demands the committed tables match value for value, exactly the
 * discipline `OG_IDLE_NODES` earned in tests/composePose.test.ts.
 *
 * Grammar facts the suites pin (probed 2026-07-28, this commit's bindata):
 *   - `walk` is 20 full frames (19 nodes each), rotation-only, looping.
 *   - `balancedhorizontalslash` is a THREE-part chain a(4)/b(9,loop)/c(7);
 *     parts a+b are full frames; part c is SPARSE — frames carry only the
 *     nodes that changed (counts 0/7/19), and playback carries the rest
 *     forward. The transcription stores frames EXACTLY as sparse as the
 *     source does; carry-forward is the A11.4 stepper's job, not the data's.
 *   - Slash frames use Flash MATRIX nodes (`a b c d`, fixed-point ×100) on
 *     some slots — notably slot 3, the weapon, mid-swing — while walk/idle
 *     are rotation-degree nodes. Both forms are stored verbatim.
 *   - Every frame omits slots 8 and 17 (the two the AS3 aliases), like idle.
 */
import { existsSync, readFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { OG_ANIMS, type OgAnimNode } from '../src/config/ogAnims';

const ANIM_NAMES = [
  'walk',
  'balancedhorizontalslash_parta',
  'balancedhorizontalslash_partb',
  'balancedhorizontalslash_partc',
] as const;

describe('A11-D structural pins — run everywhere, no reference payload needed', () => {
  it('carries exactly the four duel-loop animations of this milestone', () => {
    expect(Object.keys(OG_ANIMS).sort()).toEqual([...ANIM_NAMES].sort());
  });

  it('frame counts match the source d= attributes: walk 20, slash 4/9/7', () => {
    expect(OG_ANIMS.walk.frames.length).toBe(20);
    expect(OG_ANIMS.walk.durationFrames).toBe(20);
    expect(OG_ANIMS.balancedhorizontalslash_parta.frames.length).toBe(4);
    expect(OG_ANIMS.balancedhorizontalslash_partb.frames.length).toBe(9);
    expect(OG_ANIMS.balancedhorizontalslash_partc.frames.length).toBe(7);
  });

  it('loop flags match the source l= attributes: walk and part b loop, a and c do not', () => {
    expect(OG_ANIMS.walk.loop).toBe(true);
    expect(OG_ANIMS.balancedhorizontalslash_parta.loop).toBe(false);
    expect(OG_ANIMS.balancedhorizontalslash_partb.loop).toBe(true);
    expect(OG_ANIMS.balancedhorizontalslash_partc.loop).toBe(false);
  });

  it('walk is FULL frames — 19 nodes each, rotation-only, never a matrix', () => {
    for (const frame of OG_ANIMS.walk.frames) {
      expect(frame.length).toBe(19);
      for (const n of frame) {
        expect(n.rotationDeg).toBeTypeOf('number');
        expect(n.a).toBeUndefined();
      }
    }
  });

  it('part c is SPARSE exactly as recorded — frame node counts 19,0,…,7 pattern', () => {
    const counts = OG_ANIMS.balancedhorizontalslash_partc.frames.map((f) => f.length);
    // The source's own sparseness, pinned loosely: at least one empty frame,
    // at least one partial (<19) non-empty frame, none over 19.
    expect(Math.max(...counts)).toBeLessThanOrEqual(19);
    expect(counts.some((c) => c === 0)).toBe(true);
    expect(counts.some((c) => c > 0 && c < 19)).toBe(true);
  });

  it('the swing uses matrix nodes on the weapon slot (3) — the grammar A11.4 must play', () => {
    const hasMatrixOnWeapon = OG_ANIMS.balancedhorizontalslash_parta.frames.some((f) =>
      f.some((n) => n.slot === 3 && n.a !== undefined),
    );
    expect(hasMatrixOnWeapon).toBe(true);
  });

  it('every node is one form or the other, never both, never neither', () => {
    for (const name of ANIM_NAMES) {
      for (const frame of OG_ANIMS[name].frames) {
        for (const n of frame) {
          const rot = n.rotationDeg !== undefined;
          const mat = n.a !== undefined || n.b !== undefined || n.c !== undefined || n.d !== undefined;
          const fullMat = n.a !== undefined && n.b !== undefined && n.c !== undefined && n.d !== undefined;
          expect(rot !== mat, `anim ${name} slot ${String(n.slot)}: exactly one transform form`).toBe(true);
          if (mat) expect(fullMat, `anim ${name} slot ${String(n.slot)}: a partial matrix is corrupt`).toBe(true);
        }
      }
    }
  });

  it('slots 8 and 17 never appear — the two the AS3 aliases, same as idle', () => {
    for (const name of ANIM_NAMES) {
      for (const frame of OG_ANIMS[name].frames) {
        expect(frame.some((n) => n.slot === 8 || n.slot === 17)).toBe(false);
      }
    }
  });
});

/** The byte-check proper — parses the payload with its own independent grammar. */
const BINDATA = path.join(
  fileURLToPath(new URL('..', import.meta.url)),
  'reference',
  'extracted',
  'bindata',
  '108_1t4635s0.bin',
);
const HAVE_BINDATA = existsSync(BINDATA);

describe.skipIf(!HAVE_BINDATA)('A11-D byte-check — OG_ANIMS is a faithful transcription', () => {
  interface SourceAnim {
    readonly durationFrames: number;
    readonly loop: boolean;
    readonly frames: ReadonlyArray<readonly OgAnimNode[]>;
  }

  const fromPayload = (name: string): SourceAnim => {
    const raw = readFileSync(BINDATA, 'latin1');
    const animMatch = new RegExp(`<anim i="${name}"([^>]*)>([\\s\\S]*?)</anim>`).exec(raw);
    if (animMatch === null) throw new Error(`no <anim i="${name}"> in the bindata`);
    const [, attrs, body] = animMatch;
    if (attrs === undefined || body === undefined) throw new Error('regex groups missing');
    const duration = /d="(\d+)"/.exec(attrs)?.[1];
    if (duration === undefined) throw new Error(`anim ${name}: no d= attribute`);

    const frames: OgAnimNode[][] = [];
    for (const f of body.matchAll(/<f i="(\d+)"[^>]*>([\s\S]*?)<\/f>/g)) {
      const frameBody = f[2];
      if (frameBody === undefined) throw new Error('frame body missing');
      const nodes: OgAnimNode[] = [];
      for (const n of frameBody.matchAll(/<n ([^>/]*?)\/?>(?:<\/n>)?/g)) {
        const kv = new Map<string, number>();
        const nAttrs = n[1];
        if (nAttrs === undefined) throw new Error('node attrs missing');
        for (const p of nAttrs.matchAll(/(\w+)="(-?\d+)"/g)) {
          const key = p[1];
          const val = p[2];
          if (key === undefined || val === undefined) throw new Error('attr pair missing');
          kv.set(key, Number(val));
        }
        const slot = kv.get('i');
        const x = kv.get('x');
        const y = kv.get('y');
        if (slot === undefined || x === undefined || y === undefined) {
          throw new Error(`anim ${name}: node without i/x/y`);
        }
        const r = kv.get('r');
        nodes.push(
          r !== undefined
            ? { slot, x, y, rotationDeg: r }
            : { slot, x, y, a: kv.get('a'), b: kv.get('b'), c: kv.get('c'), d: kv.get('d') },
        );
      }
      frames.push(nodes);
    }
    return { durationFrames: Number(duration), loop: attrs.includes('l="1"'), frames };
  };

  it.each([...ANIM_NAMES])('%s matches the payload frame for frame, node for node', (name) => {
    const src = fromPayload(name);
    const mine = OG_ANIMS[name];
    expect(mine.durationFrames).toBe(src.durationFrames);
    expect(mine.loop).toBe(src.loop);
    expect(mine.frames.length).toBe(src.frames.length);
    src.frames.forEach((srcFrame, i) => {
      // JSON round-trip normalises undefined-vs-absent optional fields.
      expect(
        JSON.parse(JSON.stringify(mine.frames[i])),
        `frame ${String(i)}`,
      ).toEqual(JSON.parse(JSON.stringify(srcFrame)));
    });
  });
});
